// src/pages/BlogPage/TrendingSection.jsx
import React from 'react';
import styles from './TrendingSection.module.css';

const TrendingSection = ({ posts }) => {
  return (
    <div className={styles.trendingSection}>
      <h2>Trending</h2>
      {posts.map((post) => (
        <div key={post.id} className={styles.trendingItem}>
          <img src={post.image} alt={post.title} className={styles.trendingImage} />
          <div className={styles.trendingText}>
            <h3>{post.title}</h3>
            <p className={styles.trendingDate}>{post.date}</p>
          </div>
        </div>
      ))}
    </div>
  );
};

export default TrendingSection;
